const FILES = ["apple-touch-icon.png","assets/bad_samaritan/actions.png","assets/bad_samaritan/animations.json","assets/bad_samaritan/movement.png","assets/bad_samaritan/smoke_projectile.png","assets/bg/casa.png","assets/bg/ponte.png","assets/bg2/bolsa.png","assets/bg2/clerigos.png","assets/bg2/maia.png","assets/bg2/market.png","assets/bg2/ribeira.png","assets/bg2/saobento.png","assets/bg2/se.png","assets/bg2/subsolo.png","assets/enemies/enemies.png","assets/enemies/sprites.json","assets/enemies/weapons_fx.png","assets/layers/casa_0.png","assets/layers/casa_1.png","assets/layers/casa_2.png","assets/layers/casa_3.png","assets/layers/casa_4.png","assets/layers/cistern_0.png","assets/layers/cistern_1.png","assets/layers/cistern_2.png","assets/layers/cistern_3.png","assets/layers/cistern_4.png","assets/layers/clerigos_0.png","assets/layers/clerigos_1.png","assets/layers/clerigos_2.png","assets/layers/clerigos_3.png","assets/layers/clerigos_4.png","assets/layers/cloudtop_0.png","assets/layers/cloudtop_1.png","assets/layers/cloudtop_2.png","assets/layers/cloudtop_3.png","assets/layers/cloudtop_4.png","assets/layers/maia_0.png","assets/layers/maia_1.png","assets/layers/maia_2.png","assets/layers/maia_3.png","assets/layers/maia_4.png","assets/layers/ponte_0.png","assets/layers/ponte_1.png","assets/layers/ponte_2.png","assets/layers/ponte_3.png","assets/layers/ponte_4.png","assets/layers/ribeira_0.png","assets/layers/ribeira_1.png","assets/layers/ribeira_2.png","assets/layers/ribeira_3.png","assets/layers/ribeira_4.png","assets/layers/saobento_0.png","assets/layers/saobento_1.png","assets/layers/saobento_2.png","assets/layers/saobento_3.png","assets/layers/saobento_4.png","assets/layers/se_0.png","assets/layers/se_1.png","assets/layers/se_2.png","assets/layers/se_3.png","assets/layers/se_4.png","assets/layers/skycity_0.png","assets/layers/skycity_1.png","assets/layers/skycity_2.png","assets/layers/skycity_3.png","assets/layers/skycity_4.png","assets/layers/subsolo_0.png","assets/layers/subsolo_1.png","assets/layers/subsolo_2.png","assets/layers/subsolo_3.png","assets/layers/subsolo_4.png","assets/layers/tunnel_0.png","assets/layers/tunnel_1.png","assets/layers/tunnel_2.png","assets/layers/tunnel_3.png","assets/layers/tunnel_4.png","assets/music/night-protocol.mp3","assets/music/synthetic-pleasures.mp3","assets/music/the-witch.mp3","assets/pack3.json","assets/pack3.png","assets/palettes.json","assets/props.json","assets/props.png","favicon-32.png","game.js","icon-192.png","icon-512.png","index.html","manifest.webmanifest"];
const CACHE = 'bad-samaritan-' + VERSION;
// deployed at madeinmaia.pt as /badsamaritan-sw.js (scope /badsamaritan); elsewhere next to index.html
const BASE = self.location.pathname.endsWith('/badsamaritan-sw.js') ? '/badsamaritan/' : self.location.pathname.replace(/sw\.js$/, '');
const FRESH = new Set([BASE + 'index.html', BASE + 'game.js', BASE + 'manifest.webmanifest']);

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    await Promise.all(FILES.map((f) => fetch(BASE + f, { cache: 'reload' }).then((r) => { if (r.ok) return c.put(BASE + f, r); }).catch(() => {})));
    self.skipWaiting();
  })());
});
self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('bad-samaritan-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const isPage = req.mode === 'navigate';
  const key = isPage ? BASE + 'index.html' : url.pathname;
  if (!isPage && !url.pathname.startsWith(BASE)) return;
  if (req.headers.has('range')) return; // let the browser stream audio ranges itself
  if (isPage || FRESH.has(key)) {
    e.respondWith(fetch(req).then((r) => { if (r.ok) { const cp = r.clone(); caches.open(CACHE).then((c) => c.put(key, cp)); } return r; })
      .catch(() => caches.match(key).then((m) => m || Response.error())));
    return;
  }
  e.respondWith(caches.match(key).then((m) => m || fetch(req).then((r) => { if (r.ok) { const cp = r.clone(); caches.open(CACHE).then((c) => c.put(key, cp)); } return r; })));
});
